}
.z-10 {
  z-index: 10;
}
.flex {
  display: flex;
}
.hidden {
  display: none;
}
.size-6 {
  width: 1.5rem;
  height: 1.5rem;
}
.w-fit {
  width: -moz-fit-content;
  width: fit-content;
}
.cursor-pointer {
  cursor: pointer;
}
.items-center {
  align-items: center;
}
.gap-2 {
  gap: 0.5rem;
}
.overflow-hidden {
  overflow: hidden;
}
.rounded-full {
  border-radius: 9999px;
}
.border {
